def solve_06(data):
    from itertools import product

    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    options = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        options.append([-1] + versions)

    for vector in product(*options):
        selected = dict(zip(names, vector))
        rows = {}
        for name, version in selected.items():
            if version == -1:
                continue
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                break
            rows[name] = next(row for row in packages[name] if row["version"] == version)
        else:
            edges = {}
            reachable = set()
            pending = []
            valid = True
            for name, bounds in data["roots"].items():
                version = selected.get(name, -1)
                if version == -1 or not bounds[0] <= version <= bounds[1]:
                    valid = False
                    break
                pending.append(name)
            while valid and pending:
                name = pending.pop()
                if name in reachable:
                    continue
                if name not in rows:
                    valid = False
                    break
                reachable.add(name)
                active = [dep for dep in rows[name].get("deps", [])
                          if not dep.get("feature") or dep["feature"] in features]
                edges[name] = []
                for dep in active:
                    other = dep["name"]
                    version = selected.get(other, -1)
                    if version == -1 or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                    pending.append(other)
            if not valid or reachable != set(rows):
                continue

            finished, active = set(), set()

            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if all(acyclic(name) for name in edges):
                return {"versions": {name: version for name, version in selected.items()
                                     if version != -1}}
    return {"error": "unsatisfiable"}


def solve_07(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best = None
    for subset in combinations(jobs, data["k"]):
        ids = [job["id"] for job in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        candidate = (value, selected)
        if best is None or value > best[0] or (value == best[0] and selected < best[1]):
            best = candidate
    if best is None:
        return {"error": "impossible"}
    return {"selected": best[1], "value": best[0]}


def solve_08(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, data["coupons"], initial_mask)
    best = {start_state: data["start"]}
    queue = [(data["start"], source, data["coupons"], initial_mask)]
    while queue:
        time, node, remaining, mask = heapq.heappop(queue)
        state = (node, remaining, mask)
        if best.get(state) != time:
            continue
        if node == data["target"] and remaining == 0 and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                choices.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                remaining - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit.get(dest, 0)
                next_state = (dest, left, next_mask)
                if arrival < best.get(next_state, float("inf")):
                    best[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, left, next_mask))
    return {"arrival": None}


